module tb_TopModule;
    reg [5:0] y;
    reg       w;
    wire      Y1;
    wire      Y3;

    TopModule uut (
        .y(y),
        .w(w),
        .Y1(Y1),
        .Y3(Y3)
    );

    initial begin
        integer i, j;
        reg exp_Y1, exp_Y3;

        // Test all combinations of y (one-hot) and w
        for (i = 0; i < 6; i = i + 1) begin
            for (j = 0; j < 2; j = j + 1) begin
                y = (1 << i);
                w = j;
                #1;

                // Determine expected based on spec independently
                // A(0): w=1->B, w=0->A
                // B(1): w=1->C, w=0->D
                // C(2): w=1->E, w=0->D
                // D(3): w=1->F, w=0->A
                // E(4): w=1->E, w=0->D
                // F(5): w=1->C, w=0->D
                exp_Y1 = 0;
                exp_Y3 = 0;

                case (i)
                    0: begin // A
                        if (w == 1) exp_Y1 = 1; // goes to B
                    end
                    1: begin // B
                        if (w == 0) exp_Y3 = 1; // goes to D
                    end
                    2: begin // C
                        if (w == 0) exp_Y3 = 1; // goes to D
                    end
                    3: begin // D
                        // goes to F (w=1) or A (w=0)
                    end
                    4: begin // E
                        if (w == 0) exp_Y3 = 1; // goes to D
                    end
                    5: begin // F
                        if (w == 0) exp_Y3 = 1; // goes to D
                    end
                endcase

                if (Y1 !== exp_Y1 || Y3 !== exp_Y3) begin
                    $display("SELFFAIL: y=%b, w=%b | Got Y1=%b Y3=%b, Expected Y1=%b Y3=%b", 
                             y, w, Y1, Y3, exp_Y1, exp_Y3);
                    $display("SELFTEST FAIL: mismatch");
                    $finish;
                end
            end
        end

        // Also test non-one-hot or zero cases if needed, but spec says "Assume that a one-hot code is used"
        $display("SELFTEST PASS");
        $finish;
    end
endmodule
